html:
{% set ws = frappe.db.get_value("Institution Settings") or {} %}
{% set pc = None %}
{% if frappe.db.exists("Applicant Portal Config", "Applicant Portal Config") %}
{% set pc = frappe.get_doc("Applicant Portal Config", "Applicant Portal Config") %}
{% endif %}
{% set pace_app = None %}
{% if doc.pace_application and frappe.db.exists("PACE Application", doc.pace_application) %}
{% set pace_app = frappe.get_doc("PACE Application", doc.pace_application) %}
{% endif %}
{% set prog_title = frappe.db.get_value("PACE Programme", doc.program, "programme_name") if doc.program else "" %}
{% set pr_gateway = frappe.db.get_value("Payment Request", doc.payment_request, "payment_gateway") if doc.payment_request else "" %}

{# DYNAMIC CAMPUS RESOLUTION (NO HARDCODING) #}
{% set campus = None %}
{% if doc.campus %}
    {% set campus = frappe.get_doc("Campus", doc.campus) if frappe.db.exists("Campus", doc.campus) else None %}
{% endif %}
{% if not campus %}
    {% set campus_list = frappe.get_all("Campus", filters={"is_active": 1}, limit=1) %}
    {% if campus_list %}
        {% set campus = frappe.get_doc("Campus", campus_list[0].name) %}
    {% endif %}
{% endif %}

{# CAMPUS LOGO AND DETAILS #}
{% set logo_src = campus.logo if campus and campus.logo else "" %}
{% set inst_name = campus.campus_name if campus else ((pc.portal_title if pc else None) or ws.get("title") or _("Institution")) %}
{% set inst_addr = "" %}
{% if campus %}
    {% set inst_addr = (campus.address or "") + (", " + campus.city if campus.city else "") + (", " + campus.state if campus.state else "") %}
{% endif %}
{% if not inst_addr and pc %}
    {% set inst_addr = pc.footer_address or "" %}
{% endif %}
{% set inst_phone = campus.phone_number if campus else ((pc.footer_phone if pc else None) or "") %}

{% set pay_date_str = frappe.utils.format_datetime(doc.payment_date, "dd/MM/yyyy") if doc.payment_date else "" %}
{% set gen_date_str = frappe.utils.format_datetime(doc.generated_on, "dd/MM/yyyy HH:mm") if doc.generated_on else "" %}

{# Determine fee type label for product column #}
{% set fee_label = doc.fee_type or _("Fee") %}
{% set product_label = fee_label %}
{% if doc.fee_type and "application" in doc.fee_type|lower %}
    {% set product_label = _("Application Fee") %}
{% elif doc.fee_type and ("course" in doc.fee_type|lower or "tuition" in doc.fee_type|lower or "semester" in doc.fee_type|lower) %}
    {% set product_label = _("Course Fees - Domestic") %}
{% endif %}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,wght@0,300;0,400;0,600;0,700;1,400&display=swap%27);

    @media print {
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; }
        .receipt-page { padding: 0; }
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
        font-family: 'Source Serif 4', Georgia, 'Times New Roman', serif;
        background: #fff;
        color: #000;
    }

    .receipt-page {
        width: 100%;
        max-width: 720px;
        margin: 0 auto;
        padding: 24px 20px;
        background: #fff;
    }

    /* ── Top title ── */
    .page-title {
        text-align: center;
        font-size: 17px;
        font-weight: 700;
        margin-bottom: 16px;
        letter-spacing: 0.01em;
    }

    /* ── Outer bordered box ── */
    .receipt-box {
        border: 1.5px solid #444;
        width: 100%;
    }

    /* ── Header: logo + name + address ── */
    .receipt-header {
        display: flex;
        flex-direction: column;
        align-items: center;
        padding: 18px 20px 14px;
        border-bottom: 1.5px solid #444;
        text-align: center;
    }

    .header-logo {
        width: 72px;
        height: 72px;
        display: flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 8px;
    }

    .header-logo img {
        max-width: 100%;
        max-height: 100%;
        object-fit: contain;
    }

    .logo-placeholder {
        width: 60px;
        height: 60px;
        border: 2px solid #7a1a1a;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 4px;
    }

    .logo-placeholder svg {
        width: 36px;
        height: 36px;
        fill: #7a1a1a;
    }

    .inst-name {
        font-size: 18px;
        font-weight: 700;
        letter-spacing: 0.01em;
        margin-bottom: 4px;
    }

    .inst-address {
        font-size: 12.5px;
        line-height: 1.5;
        color: #111;
        max-width: 480px;
    }

    /* ── Info rows (application number, name) ── */
    .info-row {
        display: flex;
        border-bottom: 1.5px solid #444;
    }

    .info-row-center {
        justify-content: center;
        padding: 7px 20px;
        font-size: 13px;
    }

    .info-row-center strong {
        font-weight: 700;
    }

    /* ── Amount confirmation block ── */
    .amount-confirm {
        padding: 10px 20px;
        border-bottom: 1.5px solid #444;
        text-align: center;
        font-size: 13px;
        line-height: 1.7;
    }

    .amount-confirm .amount-val {
        font-weight: 700;
    }

    /* ── Details grid (date / payment type / transaction ID) ── */
    .details-grid {
        border-bottom: 1.5px solid #444;
    }

    .detail-row {
        display: flex;
        border-bottom: 1px solid #ccc;
    }

    .detail-row:last-child {
        border-bottom: none;
    }

    .detail-label {
        width: 170px;
        min-width: 170px;
        padding: 6px 16px 6px 20px;
        font-size: 13px;
        font-weight: 400;
        border-right: 1px solid #ccc;
        background: #fafafa;
    }

    .detail-value {
        padding: 6px 16px;
        font-size: 13px;
        font-weight: 600;
    }

    /* ── Product table ── */
    .product-table {
        width: 100%;
        border-collapse: collapse;
        border-bottom: 1.5px solid #444;
    }

    .product-table th {
        padding: 7px 12px;
        font-size: 13px;
        font-weight: 700;
        border-right: 1px solid #ccc;
        border-bottom: 1px solid #ccc;
        background: #f5f5f5;
        text-align: center;
    }

    .product-table th:last-child,
    .product-table td:last-child {
        border-right: none;
    }

    .product-table td {
        padding: 7px 12px;
        font-size: 13px;
        border-right: 1px solid #ccc;
        border-bottom: 1px solid #ccc;
        vertical-align: middle;
    }

    .product-table tr.total-row td {
        font-weight: 700;
        background: #fafafa;
    }

    .product-table tr.total-row td:first-child {
        text-align: right;
        font-weight: 700;
    }

    .product-table tr:last-child td {
        border-bottom: none;
    }

    .td-center { text-align: center; }
    .td-right  { text-align: right; }

    /* ── Amount in words ── */
    .amount-words {
        padding: 8px 20px;
        font-size: 13px;
        font-weight: 700;
        border-bottom: 1.5px solid #444;
    }

    /* ── Non-refundable note ── */
    .non-refundable {
        padding: 9px 20px;
        border-bottom: 1.5px solid #444;
        font-size: 13px;
        font-weight: 700;
        display: flex;
        align-items: center;
        gap: 8px;
        justify-content: center;
    }

    .check-icon {
        color: #1a7a1a;
        font-size: 15px;
    }

    /* ── Footer ── */
    .receipt-footer {
        padding: 8px 20px;
        text-align: center;
        font-size: 12px;
        line-height: 1.6;
    }

    .receipt-footer .generated-line {
        font-style: italic;
    }

    .receipt-footer .disclaimer {
        font-weight: 700;
    }
</style>

<div class="receipt-page">

    <div class="page-title">{{ _("Electronic Receipt") }}</div>

    <div class="receipt-box">

        {# ── HEADER ── #}
<div class="receipt-header">
<div class="header-logo">
                {% if logo_src %}
<img src="{{ logo_src }}" alt="{{ inst_name }}">
                {% else %}
<div class="logo-placeholder">
<svg viewBox="0 0 36 36" xmlns="http://www.w3.org/2000/svg">
<path d="M18 2L4 10v16l14 8 14-8V10L18 2zm0 3.2L29 11v14l-11 6.3L7 25V11L18 5.2z"/>
<path d="M18 12a6 6 0 100 12 6 6 0 000-12zm0 2a4 4 0 110 8 4 4 0 010-8z"/>
</svg>
</div>
                {% endif %}
</div>
<div class="inst-name">{{ inst_name }}</div>
            {% if inst_addr %}
<div class="inst-address">{{ inst_addr }}</div>
            {% endif %}
</div>

        {# ── APPLICATION NUMBER ── #}
<div class="info-row info-row-center">
            {{ _("Application Number") }}: <strong>&nbsp;{{ doc.pace_application or doc.name }}</strong>
</div>

        {# ── APPLICANT NAME ── #}
<div class="info-row info-row-center">
            {{ _("To") }}: <strong>&nbsp;{{ doc.applicant_name or "" }}</strong>
</div>

        {# ── AMOUNT CONFIRMATION ── #}
<div class="amount-confirm">
            {{ _("Amount submission of") }} {{ doc.currency or "INR" }} <span class="amount-val">{{ "{:,.2f}".format(doc.amount) }}</span> {{ _("is successful.") }}<br>
            {{ _("Amount received for Program") }} - <strong>{{ prog_title or doc.program or "" }}</strong>
</div>

        {# ── DETAILS GRID ── #}
<div class="details-grid">
<div class="detail-row">
<div class="detail-label">{{ _("Date of Receipt") }}</div>
<div class="detail-value">{{ pay_date_str }}</div>
</div>
<div class="detail-row">
<div class="detail-label">{{ _("Payment Type") }}</div>
<div class="detail-value">{{ pr_gateway or _("Online") }}</div>
</div>
<div class="detail-row">
<div class="detail-label">{{ _("Transaction Mode") }}</div>
<div class="detail-value">{{ _("Online") }}</div>
</div>
            {% if doc.transaction_id %}
<div class="detail-row">
<div class="detail-label">{{ _("Transaction ID") }}</div>
<div class="detail-value">{{ doc.transaction_id }}</div>
</div>
            {% endif %}
</div>

        {# ── PRODUCT TABLE ── #}
<table class="product-table">
<thead>
<tr>
<th style="width:60px;">{{ _("S.No.") }}</th>
<th>{{ _("Product") }}</th>
<th style="width:90px;">{{ _("Quantity") }}</th>
<th style="width:110px;">{{ _("Price") }}</th>
<th style="width:110px;">{{ _("Amount") }}</th>
</tr>
</thead>
<tbody>
<tr>
<td class="td-center">1</td>
<td>{{ product_label }}</td>
<td class="td-center">1</td>
<td class="td-right">{{ "{:,.2f}".format(doc.amount) }}</td>
<td class="td-right">{{ "{:,.2f}".format(doc.amount) }}</td>
</tr>
<tr class="total-row">
<td colspan="3" class="td-right">{{ _("Total") }}</td>
<td class="td-right">{{ "{:,.2f}".format(doc.amount) }}</td>
<td class="td-right">{{ "{:,.2f}".format(doc.amount) }}</td>
</tr>
</tbody>
</table>

        {# ── AMOUNT IN WORDS ── #}
<div class="amount-words">
            {{ frappe.utils.money_in_words(doc.amount, doc.currency or "INR") }}
</div>

        {# ── NON-REFUNDABLE ── #}
<div class="non-refundable">
<span class="check-icon">✓</span>
            {{ _("I accept that fee paid is non-refundable.") }}
</div>

        {# ── FOOTER ── #}
<div class="receipt-footer">
<div class="generated-line">{{ _("This is a system-generated receipt and does not require a signature.") }}</div>
<div class="disclaimer"><strong>{{ _("Disclaimer:") }}</strong> {{ _("The total charges include 18% GST") }}</div>
</div>

    </div><!-- /.receipt-box -->

</div><!-- /.receipt-page -->
